<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, useId, watch } from 'vue'
import { ElButton, ElIcon } from 'element-plus'
import { Promotion, VideoPause, ChatDotRound, ArrowRight, RefreshRight } from '@element-plus/icons-vue'
import { assistantState, activeRun, isRunning, pendingOperations, sendMessage, stopRun, loadAssistant } from '../state'
import OperationCard from './OperationCard.vue'
defineProps<{ compact?: boolean }>()
const emit = defineEmits<{ results: [] }>()
const promptId = useId()
const messages = ref<HTMLElement>(), input = ref<HTMLTextAreaElement>(), composing = ref(false)
const rows = computed(() => (assistantState.detail?.runs ?? []).map(run => {
  const items = assistantState.detail?.messages.filter(m => m.runId === run.id) ?? []
  const live = assistantState.selectedRunId === run.id ? assistantState.events.filter(e => e.kind === 'text_delta').map(e => String(e.data.text ?? '')).join('') : ''
  return { run, user: items.find(m => m.role === 'user')?.content ?? '', assistant: live || items.filter(m => m.role === 'assistant').map(m => m.content).join('\n\n') }
}))
const activity = computed(() => assistantState.events.filter(e => ['tool_started', 'tool_result', 'approval_required', 'operation_result'].includes(e.kind)).at(-1))
const activityText = computed(() => activity.value?.kind === 'tool_started' ? `正在${String(activity.value.data.title ?? '调用工具')}` : isRunning.value ? '正在处理你的请求…' : '')
let follow = true
function scroll() { const el = messages.value; if (el) follow = el.scrollHeight - el.scrollTop - el.clientHeight < 100 }
watch(() => [rows.value.map(r => r.assistant).join(''), activeRun.value?.status, assistantState.detail?.messages.length], async () => { await nextTick(); if (follow && messages.value) messages.value.scrollTop = messages.value.scrollHeight })
watch(() => assistantState.detail?.conversation.id, async () => { follow = true; await nextTick(); if (messages.value) messages.value.scrollTop = messages.value.scrollHeight })
function keydown(event: KeyboardEvent) { if (event.key === 'Enter' && !event.shiftKey && !event.isComposing && !composing.value) { event.preventDefault(); void sendMessage() } }
function suggestion(text: string) { assistantState.draft = text; void nextTick(() => input.value?.focus()) }
function canRetry(id: string) { return !activeRun.value && !assistantState.busy && !assistantState.detail?.operations.some(o => o.runId === id && ['APPROVED','EXECUTING','SUCCEEDED','UNCERTAIN'].includes(o.state)) }
function retry(id: string) { const row = rows.value.find(r => r.run.id === id); if (row && canRetry(id)) { assistantState.draft = row.user; void sendMessage() } }
onBeforeUnmount(() => { composing.value = false })
</script>
<template>
  <section class="conversation-pane" :class="{ compact }" aria-label="助手对话">
    <header class="conversation-header"><div><ElIcon><ChatDotRound /></ElIcon><strong>与助手对话</strong></div><span>{{ assistantState.status?.model || '尚未配置模型' }}</span></header>
    <div ref="messages" class="conversation-messages" role="log" aria-label="对话记录" @scroll="scroll">
      <div v-if="!rows.length" class="conversation-welcome"><img src="/assets/brand/logo-mark.svg" width="44" height="44" alt=""><h2>从一句话开始</h2><p>找歌曲、整理曲库，或查看后台任务。<br>写入前，我会把改动交给你核对。</p><div class="conversation-suggestions"><button @click="suggestion('看看现在有哪些后台任务')">看看现在有哪些后台任务</button><button @click="suggestion('查询曲库里的陈奕迅歌曲')">查询曲库里的陈奕迅歌曲</button><button @click="suggestion('检查模型和计算节点的可用状态')">检查模型和计算节点状态</button></div></div>
      <template v-for="row in rows" :key="row.run.id"><article class="message user"><small>你</small><p>{{ row.user }}</p></article><article v-if="row.assistant" class="message assistant"><small>SingVerse 助手</small><p>{{ row.assistant }}</p></article><div v-if="row.run.error" class="run-error" role="status"><p>{{ row.run.error }}</p><ElButton v-if="row.run.status === 'FAILED' && canRetry(row.run.id)" text @click="retry(row.run.id)">重新尝试</ElButton><p v-else-if="row.run.status === 'FAILED'">请先核对执行记录，再继续对话。</p></div></template>
      <div v-if="activityText" class="conversation-activity" role="status"><span class="activity-dot" />{{ activityText }}</div>
      <div v-if="pendingOperations.length" class="pending-hint"><strong>{{ pendingOperations.length }} 项操作等待确认</strong><p>请核对操作对象、改动和影响后选择。</p><ElButton v-if="!compact" text type="primary" @click="emit('results')">查看左侧确认内容</ElButton><OperationCard v-for="op in compact ? pendingOperations : []" :key="op.id" :operation="op" /></div>
    </div>
    <div v-if="assistantState.status && !assistantState.status.ready" class="assistant-setup"><strong>先配置助手模型</strong><p>{{ assistantState.status.message }}</p><RouterLink :to="assistantState.status.settingsPage">前往助手设置 <ElIcon><ArrowRight /></ElIcon></RouterLink></div>
    <div v-if="assistantState.error" class="conversation-error" role="alert"><p>{{ assistantState.error }}</p><ElButton text :icon="RefreshRight" :disabled="assistantState.loading || assistantState.busy" @click="loadAssistant()">重新加载</ElButton></div>
    <form class="conversation-composer" @submit.prevent="sendMessage">
      <label class="sr-only" :for="promptId">给助手发送消息</label><textarea :id="promptId" ref="input" v-model="assistantState.draft" rows="3" maxlength="8000" :disabled="!assistantState.status?.ready || assistantState.loading" placeholder="告诉我你想做什么…" @keydown="keydown" @compositionstart="composing = true" @compositionend="composing = false" />
      <div class="composer-actions"><span>{{ activeRun?.status === 'WAITING' ? '等待确认后继续' : isRunning ? '正在回复' : 'Enter 发送 · Shift + Enter 换行' }}</span><ElButton v-if="activeRun" :icon="VideoPause" :disabled="assistantState.busy" @click="stopRun">停止对话</ElButton><ElButton v-else type="primary" :icon="Promotion" native-type="submit" :disabled="!assistantState.draft.trim() || !assistantState.status?.ready || assistantState.busy" :loading="assistantState.busy">发送</ElButton></div>
    </form>
    <p class="conversation-note">查询直接执行，写入由你确认。停止对话不会取消业务任务。</p>
  </section>
</template>
<style scoped>
