on-card){margin:16px 0 0;padding:14px}.conversation-activity{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--sv-text-secondary);padding:10px 0}.activity-dot{width:7px;height:7px;background:var(--sv-accent-primary);border-radius:50%;flex-shrink:0}.conversation-composer{margin:16px 20px 0;border:1px solid var(--sv-border-default);border-radius:12px;padding:12px;background:var(--sv-surface-1)}.conversation-composer:focus-within{border-color:var(--sv-accent-primary);box-shadow:0 0 0 2px var(--sv-accent-soft)}textarea{box-sizing:border-box;display:block;width:100%;resize:none;min-height:74px;border:0;outline:0;font:inherit;font-size:14px;line-height:1.7;background:transparent;color:var(--sv-text-primary);padding:0}textarea::placeholder{color:var(--sv-text-secondary)}.composer-actions{display:flex;align-items:center;justify-content:space-between;gap:8px}.composer-actions>span{font-size:12px;color:var(--sv-text-secondary)}.composer-actions .el-button{min-height:44px}.conversation-note{font-size:12px;line-height:1.7;color:var(--sv-text-secondary);margin:10px 20px 16px;text-align:center}.assistant-setup,.conversation-error,.run-error{padding:16px;font-size:14px;line-height:1.7;background:var(--sv-surface-2);border-radius:8px}.assistant-setup,.conversation-error{margin:12px 20px 0}.assistant-setup p,.conversation-error p{margin:6px 0;color:var(--sv-text-secondary)}.assistant-setup a{display:inline-flex;gap:8px;align-items:center;min-height:44px;font-size:13px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.compact .conversation-header{display:none}.compact .conversation-messages{padding:20px;min-height:160px}.compact .conversation-welcome{padding:0}.compact .conversation-welcome h2{font-size:21px}.compact .conversation-suggestions{margin-top:20px}.compact .conversation-composer{margin:12px 14px 0}.compact .composer-actions>span{max-width:145px}.compact .conversation-note{margin:8px 14px 12px}.compact .conversation-note{font-size:12px}.compact{height:480px;max-height:55dvh}@media(max-width:600px){textarea{font-size:16px}.conversation-header{padding:16px 20px}.conversation-messages{padding:20px}.composer-actions>span{max-width:150px}.compact{max-height:56dvh}}
</style>
